Here is the commit message:
can: j1939: transport: j1939_session_tx_dat(): fix
 use-after-free read in j1939_tp_txtimer()

The current stack implementation do not support ECTS requests of not
aligned TP sized blocks.

If ECTS will request a block with size and offset spanning two TP
blocks, this will cause memcpy() to read beyond the queued skb (which
does only contain one TP sized block).

Sometimes KASAN will detect this read if the memory region beyond the
skb was previously allocated and freed. In other situations it will stay
undetected. The ETP transfer in any case will be corrupted.

This patch adds a sanity check to avoid this kind of read and abort the
session with error J1939_XTP_ABORT_ECTS_TOO_BIG.

Reported-by: syzbot+5322482fe520b02aea30@syzkaller.appspotmail.com
Fixes: 9d71dd0c7009 ("can: add support of SAE J1939 protocol")
Cc: linux-stable <stable@vger.kernel.org> # >= v5.4
Signed-off-by: Oleksij Rempel <o.rempel@pengutronix.de>
Link: https://lore.kernel.org/r/20200807105200.26441-3-o.rempel@pengutronix.de
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
The bug is caused by the current stack implementation not supporting ECTS requests for TP-sized blocks that are not aligned. When an ECTS request spans two TP blocks, the `memcpy()` function attempts to read beyond the allocated memory of the queued socket buffer (skb), leading to a use-after-free read. This can result in memory corruption, as the read may access freed memory or unallocated regions, which can go undetected in some cases.

Here is the patch:

 static int j1939_session_tx_dat(struct j1939_session *session)
 {
 	struct j1939_priv *priv = session->priv;
 	struct j1939_sk_buff_cb *skcb;
 	int offset, pkt_done, pkt_end;
 	unsigned int len, pdelay;
 	struct sk_buff *se_skb;
 	const u8 *tpdat;
 	int ret = 0;
 	u8 dat[8];

 	se_skb = j1939_session_skb_find(session);
 	if (!se_skb)
 		return -ENOBUFS;

 	skcb = j1939_skb_to_cb(se_skb);
 	tpdat = se_skb->data;
 	ret = 0;
 	pkt_done = 0;
 	if (session->skcb.addr.type != J1939_ETP &&
 	    j1939_cb_is_broadcast(&session->skcb))
 		pkt_end = session->pkt.total;
 	else
 		pkt_end = session->pkt.last;

 	while (session->pkt.tx < pkt_end) {
 		dat[0] = session->pkt.tx - session->pkt.dpo + 1;
 		offset = (session->pkt.tx * 7) - skcb->offset;
 		len =  se_skb->len - offset;
 		if (len > 7)
 			len = 7;

+		if (offset + len > se_skb->len) {
+			netdev_err_once(priv->ndev,
+					"%s: 0x%p: requested data outside of queued buffer: offset %i, len %i, pkt.tx: %i\n",
+					__func__, session, skcb->offset, se_skb->len , session->pkt.tx);
+			return -EOVERFLOW;
+		}
+
+		if (!len) {
+			ret = -ENOBUFS;
+			break;
+		}
+
 		memcpy(&dat[1], &tpdat[offset], len);
 		ret = j1939_tp_tx_dat(session, dat, len + 1);
 		if (ret < 0) {
 			/* ENOBUS == CAN interface TX queue is full */
 			if (ret != -ENOBUFS)
 				netdev_alert(priv->ndev,
 					     "%s: 0x%p: queue data error: %i\n",
 					     __func__, session, ret);
 			break;
 		}

 		session->last_txcmd = 0xff;
 		pkt_done++;
 		session->pkt.tx++;
 		pdelay = j1939_cb_is_broadcast(&session->skcb) ? 50 :
 			j1939_tp_packet_delay;

 		if (session->pkt.tx < session->pkt.total && pdelay) {
 			j1939_tp_schedule_txtimer(session, pdelay);
 			break;
 		}
 	}

 	if (pkt_done)
 		j1939_tp_set_rxtimeout(session, 250);

 	return ret;
 }


 static enum hrtimer_restart j1939_tp_txtimer(struct hrtimer *hrtimer)
 {
 	struct j1939_session *session =
 		container_of(hrtimer, struct j1939_session, txtimer);
 	struct j1939_priv *priv = session->priv;
 	int ret = 0;

 	if (session->skcb.addr.type == J1939_SIMPLE) {
 		ret = j1939_simple_txnext(session);
 	} else {
 		if (session->transmission)
 			ret = j1939_xtp_txnext_transmiter(session);
 		else
 			ret = j1939_xtp_txnext_receiver(session);
 	}

 	switch (ret) {
 	case -ENOBUFS:
 		/* Retry limit is currently arbitrary chosen */
 		if (session->tx_retry < J1939_XTP_TX_RETRY_LIMIT) {
 			session->tx_retry++;
 			j1939_tp_schedule_txtimer(session,
 						  10 + prandom_u32_max(16));
 		} else {
 			netdev_alert(priv->ndev, "%s: 0x%p: tx retry count reached\n",
 				     __func__, session);
 			session->err = -ENETUNREACH;
 			j1939_session_rxtimer_cancel(session);
 			j1939_session_deactivate_activate_next(session);
 		}
 		break;
 	case -ENETDOWN:
 		/* In this case we should get a netdev_event(), all active
 		 * sessions will be cleared by
 		 * j1939_cancel_all_active_sessions(). So handle this as an
 		 * error, but let j1939_cancel_all_active_sessions() do the
 		 * cleanup including propagation of the error to user space.
 		 */
 		break;
+	case -EOVERFLOW:
+		j1939_session_cancel(session, J1939_XTP_ABORT_ECTS_TOO_BIG);
+		break;
 	case 0:
 		session->tx_retry = 0;
 		break;
 	default:
 		netdev_alert(priv->ndev, "%s: 0x%p: tx aborted with unknown reason: %i\n",
 			     __func__, session, ret);
 		if (session->skcb.addr.type != J1939_SIMPLE) {
 			j1939_session_cancel(session, J1939_XTP_ABORT_OTHER);
 		} else {
 			session->err = ret;
 			j1939_session_rxtimer_cancel(session);
 			j1939_session_deactivate_activate_next(session);
 		}
 	}

 	j1939_session_put(session);

 	return HRTIMER_NORESTART;
 }



