{
	struct j1939_priv *priv = session->priv;

	WARN_ON_ONCE(!err);

	session->err = j1939_xtp_abort_to_errno(priv, err);
	/* do not send aborts on incoming broadcasts */
	if (!j1939_cb_is_broadcast(&session->skcb)) {
		session->state = J1939_SESSION_WAITING_ABORT;
